Below is a drop-in rewrite preserving the same public class/function signatures and return types. It uses adjacency-list traversal plus a priority queue for Dijkstra, BFS for reachability, and BFS over an undirected view for weakly connected components.

```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from collections import deque


@dataclass
class Edge:
    src: int
    dst: int
    weight: float


class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


class _IndexedMinHeap:
    """Min-heap with decrease-key support.

    Keeps at most one heap entry per node, so heap size is O(V).
    """

    def __init__(self):
        self._heap: List[Tuple[float, int]] = []
        self._pos: Dict[int, int] = {}

    def __bool__(self) -> bool:
        return bool(self._heap)

    @staticmethod
    def _less(a: Tuple[float, int], b: Tuple[float, int]) -> bool:
        return a[0] < b[0] or (a[0] == b[0] and a[1] < b[1])

    def _swap(self, i: int, j: int) -> None:
        heap = self._heap
        heap[i], heap[j] = heap[j], heap[i]
        self._pos[heap[i][1]] = i
        self._pos[heap[j][1]] = j

    def _sift_up(self, i: int) -> None:
        while i > 0:
            parent = (i - 1) // 2
            if not self._less(self._heap[i], self._heap[parent]):
                break
            self._swap(i, parent)
            i = parent

    def _sift_down(self, i: int) -> None:
        n = len(self._heap)
        while True:
            left = 2 * i + 1
            right = left + 1
            smallest = i

            if left < n and self._less(self._heap[left], self._heap[smallest]):
                smallest = left
            if right < n and self._less(self._heap[right], self._heap[smallest]):
                smallest = right

            if smallest == i:
                break

            self._swap(i, smallest)
            i = smallest

    def push_or_decrease(self, node: int, priority: float) -> None:
        idx = self._pos.get(node)

        if idx is None:
            self._pos[node] = len(self._heap)
            self._heap.append((priority, node))
            self._sift_up(len(self._heap) - 1)
        elif priority < self._heap[idx][0]:
            self._heap[idx] = (priority, node)
            self._sift_up(idx)

    def pop(self) -> Tuple[float, int]:
        if not self._heap:
            raise IndexError("pop from empty heap")

        root = self._heap[0]
        last = self._heap.pop()
        del self._pos[root[1]]

        if self._heap:
            self._heap[0] = last
            self._pos[last[1]] = 0
            self._sift_down(0)

        return root


def _ensure_non_negative_weights(graph: WeightedGraph) -> None:
    """Dijkstra requires non-negative edge weights."""
    for edge in graph._edges:
        if edge.weight < 0:
            raise ValueError("Dijkstra shortest-path functions require non-negative edge weights")


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
    stop_after: Optional[int] = None,
) -> Tuple[Dict[int, float], Dict[int, Optional[int]], List[int]]:
    """Run Dijkstra from source.

    Returns:
        dist: finalized shortest distances for reached nodes
        prev: predecessor map for path reconstruction
        order: nodes in finalized nondecreasing-distance order

    If target is supplied, stops once target is finalized.
    If stop_after is supplied, stops after that many non-source nodes are finalized.
    """
    if source not in graph.adj:
        return {}, {}, []

    _ensure_non_negative_weights(graph)

    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    settled: Set[int] = set()
    order: List[int] = []

    heap = _IndexedMinHeap()
    heap.push_or_decrease(source, 0.0)

    non_source_finalized = 0

    while heap:
        current_dist, node = heap.pop()

        if node in settled:
            continue

        settled.add(node)
        order.append(node)

        if target is not None and node == target:
            break

        if node != source and stop_after is not None:
            non_source_finalized += 1
            if non_source_finalized >= stop_after:
                break

        for neighbor, weight in graph.neighbors(node):
            if neighbor in settled:
                continue

            new_dist = current_dist + weight
            if new_dist < dist.get(neighbor, float("inf")):
                dist[neighbor] = new_dist
                prev[neighbor] = node
                heap.push_or_decrease(neighbor, new_dist)

    return dist, prev, order


def _reconstruct_path(
    prev: Dict[int, Optional[int]],
    source: int,
    target: int,
) -> List[int]:
    if target not in prev:
        return []

    path: List[int] = []
    current: Optional[int] = target

    while current is not None:
        path.append(current)
        if current == source:
            break
        current = prev.get(current)

    path.reverse()

    if not path or path[0] != source:
        return []

    return path


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.

    Returns (distance, path) or (None, []) if unreachable.

    Complexity: O((V + E) log V).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev, _ = _dijkstra(graph, source, target=target)

    if target not in dist:
        return None, []

    return dist[target], _reconstruct_path(prev, source, target)


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.

    Returns {node: (distance, path)}.

    Complexity:
        Dijkstra pass: O((V + E) log V)
        Path materialization: O(total returned path length)
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist, prev, _ = _dijkstra(graph, source)

    result: Dict[int, Tuple[float, List[int]]] = {}
    for node in nodes:
        if node in dist:
            result[node] = (dist[node], _reconstruct_path(prev, source, node))

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.

    Returns list of (node_id, distance) sorted by distance.

    Complexity: early-terminating Dijkstra, avoiding all path reconstruction/sorting.
    """
    if k <= 0:
        return []

    if source not in graph.nodes:
        return []

    dist, _, order = _dijkstra(graph, source, stop_after=k)

    result: List[Tuple[int, float]] = []
    for node in order:
        if node == source:
            continue

        result.append((node, dist[node]))
        if len(result) == k:
            break

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Complexity: O(V + E).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False

    queue = deque([source])
    visited: Set[int] = {source}

    while queue:
        node = queue.popleft()

        if node == target:
            return True

        for neighbor, _ in graph.neighbors(node):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components, treating directed edges as undirected.

    Complexity: O(V + E).
    """
    nodes = graph.nodes
    undirected: Dict[int, List[int]] = {node: [] for node in nodes}

    for edge in graph._edges:
        undirected[edge.src].append(edge.dst)
        undirected[edge.dst].append(edge.src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for start in nodes:
        if start in visited:
            continue

        component: Set[int] = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            node = queue.popleft()
            component.add(node)

            for neighbor in undirected[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        components.append(component)

    return components
```

Note: the shortest-path functions now use Dijkstra, so edge weights must be non-negative. Supporting negative weights while also guaranteeing `O((V + E) log V)` shortest paths is not generally possible.
